{"title":"What regressed","type":"vega","aggs":[],"params":{"spec":"{
    "$schema": "https://vega.github.io/schema/vega-lite/v4.json",
    "title": "What regressed",
    "data": {
        "url": {
            "%context%": true,
            "%timefield%": "@timestamp",
            "index": "app-logs-*",
            "body": {
                "size": 0,
                "aggs": {
                    "shapes": {
                        "terms": {
                            "field": "os.hash",
                            "size": 50
                        },
                        "aggs": {
                            "before": {
                                "filter": {
                                    "range": {
                                        "@timestamp": {
                                            "%timefilter%": true,
                                            "shift": 1,
                                            "unit": "hour"
                                        }
                                    }
                                },
                                "aggs": {
                                    "p95": {
                                        "percentiles": {
                                            "field": "took",
                                            "percents": [
                                                95
                                            ]
                                        }
                                    }
                                }
                            },
                            "after": {
                                "filter": {
                                    "range": {
                                        "@timestamp": {
                                            "%timefilter%": true
                                        }
                                    }
                                },
                                "aggs": {
                                    "p95": {
                                        "percentiles": {
                                            "field": "took",
                                            "percents": [
                                                95
                                            ]
                                        }
                                    }
                                }
                            },
                            "established": {
                                "bucket_selector": {
                                    "buckets_path": {
                                        "b": "before>_count"
                                    },
                                    "script": "params.b > 0"
                                }
                            },
                            "slowdown": {
                                "bucket_script": {
                                    "buckets_path": {
                                        "b": "before>p95[95.0]",
                                        "a": "after>p95[95.0]"
                                    },
                                    "script": "params.b == 0 ? 0 : params.a / params.b"
                                }
                            },
                            "worst": {
                                "bucket_sort": {
                                    "sort": [
                                        {
                                            "slowdown": {
                                                "order": "desc"
                                            }
                                        }
                                    ],
                                    "size": 3
                                }
                            },
                            "shape": {
                                "terms": {
                                    "field": "os.sig",
                                    "size": 1
                                }
                            }
                        }
                    }
                }
            }
        },
        "format": {
            "property": "aggregations.shapes.buckets"
        }
    },
    "mark": {
        "type": "bar",
        "tooltip": true
    },
    "encoding": {
        "y": {
            "field": "key",
            "type": "nominal",
            "title": "shape",
            "sort": {
                "field": "slowdown.value",
                "order": "descending"
            }
        },
        "x": {
            "field": "slowdown.value",
            "type": "quantitative",
            "title": "x"
        },
        "tooltip": [
            {
                "field": "key",
                "type": "nominal",
                "title": "hash"
            },
            {
                "field": "shape.buckets[0].key",
                "type": "nominal",
                "title": "signature"
            },
            {
                "field": "slowdown.value",
                "type": "quantitative",
                "title": "x"
            },
            {
                "field": "doc_count",
                "type": "quantitative",
                "title": "records"
            }
        ]
    }
}"}}

{"title":"Shapes the release added","type":"vega","aggs":[],"params":{"spec":"{
    "$schema": "https://vega.github.io/schema/vega-lite/v4.json",
    "title": "Shapes the release added",
    "data": {
        "url": {
            "%context%": true,
            "%timefield%": "@timestamp",
            "index": "app-logs-*",
            "body": {
                "size": 0,
                "aggs": {
                    "shapes": {
                        "terms": {
                            "field": "os.hash",
                            "size": 100
                        },
                        "aggs": {
                            "before": {
                                "filter": {
                                    "range": {
                                        "@timestamp": {
                                            "%timefilter%": true,
                                            "shift": 1,
                                            "unit": "hour"
                                        }
                                    }
                                }
                            },
                            "after": {
                                "filter": {
                                    "range": {
                                        "@timestamp": {
                                            "%timefilter%": true
                                        }
                                    }
                                }
                            },
                            "only_after": {
                                "bucket_selector": {
                                    "buckets_path": {
                                        "b": "before>_count",
                                        "a": "after>_count"
                                    },
                                    "script": "params.b == 0 && params.a > 0"
                                }
                            },
                            "first_seen": {
                                "min": {
                                    "field": "@timestamp"
                                }
                            },
                            "shape": {
                                "terms": {
                                    "field": "os.sig",
                                    "size": 1
                                }
                            }
                        }
                    }
                }
            }
        },
        "format": {
            "property": "aggregations.shapes.buckets"
        }
    },
    "mark": {
        "type": "bar",
        "tooltip": true
    },
    "encoding": {
        "y": {
            "field": "key",
            "type": "nominal",
            "title": "shape",
            "sort": {
                "field": "doc_count",
                "order": "descending"
            }
        },
        "x": {
            "field": "doc_count",
            "type": "quantitative",
            "title": "runs"
        },
        "tooltip": [
            {
                "field": "key",
                "type": "nominal",
                "title": "hash"
            },
            {
                "field": "shape.buckets[0].key",
                "type": "nominal",
                "title": "signature"
            },
            {
                "field": "doc_count",
                "type": "quantitative",
                "title": "runs"
            },
            {
                "field": "doc_count",
                "type": "quantitative",
                "title": "records"
            }
        ]
    }
}"}}
